import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.FormElement;

public class Probe {
    static void run(String label, String html) {
        Document doc = Jsoup.parse(html);
        FormElement form = (FormElement) doc.selectFirst("form");
        StringBuilder sb = new StringBuilder();
        form.formData().forEach(kv -> { if (sb.length()>0) sb.append('&'); sb.append(kv.key()).append('=').append(kv.value()); });
        System.out.println(label + " => " + sb);
        System.out.println(doc.body().html().replace("\n", ""));
        System.out.println();
    }
    public static void main(String[] a) {
        run("legend-nested-fieldset",
            "<form id=f><fieldset disabled><legend><input name=leg value=L>" +
            "<fieldset><input name=c value=C></fieldset></legend>" +
            "<input name=a value=A></fieldset></form>");
    }
}
