import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class P3 {
    static String data(FormElement f) {
        StringBuilder sb = new StringBuilder();
        f.formData().forEach(kv -> { if (sb.length()>0) sb.append('&'); sb.append(kv.key()).append('=').append(kv.value()); });
        return sb.toString();
    }
    static void t(String label, String actual, String expected) {
        System.out.println((actual.equals(expected) ? "PASS " : "FAIL ") + label + " => [" + actual + "] expected [" + expected + "]");
    }
    public static void main(String[] a) {
        // 1. external control sitting in another form's disabled fieldset -> excluded (fieldset rule ignores form owner)
        Document d1 = Jsoup.parse("<form id=f></form><form id=g><fieldset disabled>" +
            "<input form=f name=x value=1></fieldset>" +
            "<legend-less? no>" + "</form>");
        t("external-in-other-disabled-fieldset", data(d1.expectForm("#f")), "");

        // 2. external control in other form's FIRST LEGEND of disabled fieldset -> not fieldset-disabled, submits to owner
        Document d2 = Jsoup.parse("<form id=f></form><form id=g><fieldset disabled>" +
            "<legend><input form=f name=x value=1></legend></fieldset></form>");
        t("external-in-other-legend-exempt", data(d2.expectForm("#f")), "x=1");

        // 3. toggle disabled after parse
        Document d3 = Jsoup.parse("<form id=f><input name=a value=1 disabled><input name=b value=2></form>");
        FormElement f3 = d3.expectForm("#f");
        t("disabled-initially", data(f3), "b=2");
        d3.selectFirst("[name=a]").removeAttr("disabled");
        t("reenabled", data(f3), "a=1&b=2");
        d3.selectFirst("[name=b]").attr("disabled", "");
        t("newly-disabled", data(f3), "a=1");

        // 4. select inside exempt first legend
        Document d4 = Jsoup.parse("<form id=f><fieldset disabled><legend>" +
            "<select name=s><option value=a selected><option value=b selected></select></legend>" +
            "<select name=s2><option value=x selected></select></fieldset></form>");
        t("select-in-legend", data(d4.expectForm("#f")), "s=a");

        // 5. option without value attr -> browser submits option text
        Document d5 = Jsoup.parse("<form id=f><select name=s><option selected>foo</option></select></form>");
        t("option-text-fallback", data(d5.expectForm("#f")), "s=foo");

        // 6. disabled attr on control inside exempt legend still excluded
        Document d6 = Jsoup.parse("<form id=f><fieldset disabled><legend>" +
            "<input name=a value=1 disabled><input name=b value=2></legend></fieldset></form>");
        t("own-disabled-in-legend", data(d6.expectForm("#f")), "b=2");

        // 7. outer disabled fieldset, inner legend must not re-enable
        Document d7 = Jsoup.parse("<form id=f><fieldset disabled>" +
            "<input name=a value=1>" +
            "<fieldset><legend><input name=b value=2></legend></fieldset>" +
            "</fieldset></form>");
        t("inner-legend-no-rescue", data(d7.expectForm("#f")), "");

        // 8. multi-select toggling multiple attr dynamically
        Document d8 = Jsoup.parse("<form id=f><select name=s><option value=a selected><option value=b selected></select></form>");
        FormElement f8 = d8.expectForm("#f");
        t("single-default", data(f8), "s=a");
        d8.selectFirst("select").attr("multiple", "");
        t("multiple-added", data(f8), "s=a&s=b");

        // 9. dynamic option edits
        Document d9 = Jsoup.parse("<form id=f><select name=s><option value=a><option value=b selected disabled></select></form>");
        t("sel-fallback-disabled-selected", data(d9.expectForm("#f")), "s=a");
