            "<input form=f name=e2 value=2><form id=f></form><input form=f name=e3 value=3>";
        // note: two forms id=f; first wins external refs
        Document db = Jsoup.parse(hb);
        t("interleaved-order", data(db.forms().get(0)), "e1=0&d1=1&e2=2&e3=3");
        t("second-idf-empty", data(db.forms().get(1)), "");

        // C. checkbox inside disabled fieldset first legend, checked
        String hc = "<form id=f><fieldset disabled><legend>" +
            "<input type=checkbox name=c checked value=Y><input type=radio name=r checked value=R>" +
            "</legend><input type=checkbox name=c2 checked></fieldset></form>";
        t("checked-in-legend", data(Jsoup.parse(hc).expectForm("#f")), "c=Y&r=R");

        // D. fieldset disabled added after parse dynamically
        String hd = "<form id=f><fieldset id=fs><input name=a value=1><legend><input name=l value=2></legend></fieldset></form>";
        Document dd = Jsoup.parse(hd);
        FormElement fd = dd.expectForm("#f");
        t("fs-enabled-before", data(fd), "a=1&l=2");
        dd.selectFirst("#fs").attr("disabled","");
        // after disabling: legend here is NOT the first child (input a comes first)? legend position:
        t("fs-disabled-after", data(fd), "l=2");

        // E. legend that is first legend but not first child
        String he = "<form id=f><fieldset disabled><p>x</p><legend><input name=l value=1></legend>" +
            "<input name=a value=2></fieldset></form>";
        t("legend-not-first-child", data(Jsoup.parse(he).expectForm("#f")), "l=1");

        // F. two legends, control in second -> excluded
        String hf = "<form id=f><fieldset disabled><legend>cap</legend><legend><input name=l value=1></legend>" +
