import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class P10 {
    static String data(FormElement f) {
        StringBuilder sb = new StringBuilder();
        f.formData().forEach(kv -> { if (sb.length()>0) sb.append('&'); sb.append(kv.key()).append('=').append(kv.value()); });
        return sb.toString();
    }
    static void t(String label, String actual, String expected) {
        System.out.println((actual.equals(expected) ? "PASS " : "FAIL ") + label + " => [" + actual + "] expected [" + expected + "]");
    }
    public static void main(String[] a) {
        // append fostered content into an existing form
        Document d = Jsoup.parse("<form id=f></form>");
        FormElement f = d.expectForm("#f");
        f.append("<table><tr><td><input name=x value=1></td></tr></table>");
        System.out.println(d.body().html().replaceAll("\\n\\s*",""));
        t("fragment-foster-into-form", data(f), "x=1");

        // html() reset of form with table content
        Document d2 = Jsoup.parse("<body />");
        d2.body().html("<form id=f><table><tr><td><input name=y value=2></td></tr></table></form>");
        t("body-html-foster", data(d2.expectForm("#f")), "y=2");

        // simple append retained
        Document d3 = Jsoup.parse("<form id=f />");
        d3.expectForm("#f").append("<input name=z value=3>");
        t("simple-append", data(d3.expectForm("#f")), "z=3");

        // append external form= control to body (fragment context body)
        Document d4 = Jsoup.parse("<form id=f></form>");
        d4.body().append("<input form=f name=e value=4>");
        t("fragment-external", data(d4.expectForm("#f")), "e=4");

        // nested normal control appended into a div inside the form
        Document d5 = Jsoup.parse("<form id=f><div id=w></div></form>");
        d5.selectFirst("#w").append("<input name=n value=5>");
        t("append-into-nested-div", data(d5.expectForm("#f")), "n=5");
    }
}
