import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class P11 {
    static String chain(Node e) {
        StringBuilder sb = new StringBuilder();
        for (Node n = e; n != null; n = n.parentNode()) sb.append(n.nodeName()).append('>');
        return sb.toString();
    }
    public static void main(String[] a) {
        String html = "<table><form id=f><tr><td><input name=user value=u></td>" +
            "<td><input name=pass value=p></td></tr></form></table>";
        Document doc = Jsoup.parse(html);
        System.out.println("BEFORE: " + doc.body().html().replaceAll("\\n\\s*",""));
        Element user = doc.selectFirst("[name=user]");
        doc.body().appendChild(user);
        System.out.println("after move user, table parent=" + doc.selectFirst("table").parent().nodeName());
        Element table = doc.selectFirst("table");
        Element pass = doc.selectFirst("[name=pass]");
        System.out.println("pass chain: " + chain(pass));
        System.out.println("form chain: " + chain(doc.expectForm("#f")));
        table.remove();
        System.out.println("AFTER remove table, pass parentNode=" + pass.parentNode());
        System.out.println("pass root chain: " + chain(pass));
        StringBuilder sb = new StringBuilder();
        doc.expectForm("#f").formData().forEach(kv -> sb.append(kv.key()).append('=').append(kv.value()).append(' '));
        System.out.println("data: " + sb);
    }
}
