import org.jsoup.Jsoup;
import org.jsoup.nodes.*;

public class P12 {
    static String data(FormElement f) {
        StringBuilder sb = new StringBuilder();
        f.formData().forEach(kv -> { if (sb.length()>0) sb.append('&'); sb.append(kv.key()).append('=').append(kv.value()); });
        return sb.toString();
    }
    static void t(String label, String actual, String expected) {
        System.out.println((actual.equals(expected) ? "PASS " : "FAIL ") + label + " => [" + actual + "] expected [" + expected + "]");
    }
    public static void main(String[] a) {
        // fostered form has non-empty linkedEls; clone must not wipe the original's links
        Document d = Jsoup.parse("<table><form id=f><tr><td><input name=user value=u></td>" +
            "<td><input name=pass value=p></td></tr></form></table>");
        FormElement f = d.expectForm("#f");
        t("before-clone", data(f), "user=u&pass=p");
        FormElement c = f.clone();
        t("clone-orphan", data(c), "user=u&pass=p"); // descendants retained
        t("original-after-clone", data(f), "user=u&pass=p"); // links still intact
        assertEquals(f.elements().size(), 2);
    }
    static void assertEquals(int x, int y) { if (x != y) throw new AssertionError(x+" != "+y); }
}
