        t("hidden-own-disabled", data(Jsoup.parse("<form id=f><input type=hidden name=h value=H disabled>" +
            "<input name=a value=1></form>").expectForm("#f")), "a=1");
        // two forms, control parser-linked to f moved into g via DOM (no form attr) -> belongs to g
        Document d = Jsoup.parse("<form id=f><div><input name=a value=1></div></form><form id=g></form>");
        Element ctl = d.selectFirst("[name=a]");
        d.expectForm("#g").appendChild(ctl);
        t("moved-into-g-f", data(d.expectForm("#f")), "");
        t("moved-into-g-g", data(d.expectForm("#g")), "a=1");
    }
}
